from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class Certificate:
    level: int
    witness: int
    divisible_at_level: bool
    divisible_at_next: bool

def certificates(max_level: int) -> list[Certificate]:
    if max_level < 0:
        raise ValueError("max_level must be nonnegative")
    answer: list[Certificate] = []
    for n in range(max_level + 1):
        witness = 2 ** n
        answer.append(Certificate(n, witness, witness % (2 ** n) == 0,
                                  witness % (2 ** (n + 1)) == 0))
    return answer

if __name__ == "__main__":
    for c in certificates(12):
        print(c)

from __future__ import annotations
from math import inf
from typing import Callable

def v2(x: int) -> int | float:
    if x == 0:
        return inf
    n = 0
    x = abs(x)
    while x % 2 == 0:
        x //= 2
        n += 1
    return n

def binomial_two(x: int) -> int:
    return x * (x - 1) // 2

def sampled_depth(f: Callable[[int], int], start: int, stop: int) -> int | float:
    return min(v2(f(x)) for x in range(start, stop + 1))

if __name__ == "__main__":
    for scale in range(7):
        f = lambda x, scale=scale: (2 ** scale) * binomial_two(x)
        print(scale, sampled_depth(f, -20, 20))

from __future__ import annotations
from typing import Sequence

def membership_profile(values: Sequence[int], max_level: int) -> list[bool]:
    if max_level < 0:
        raise ValueError("max_level must be nonnegative")
    return [all(v % (2 ** n) == 0 for v in values) for n in range(max_level + 1)]

def first_failed_level(values: Sequence[int], max_level: int) -> int | None:
    for n, passes in enumerate(membership_profile(values, max_level)):
        if not passes:
            return n
    return None

if __name__ == "__main__":
    samples = {
        "constant 8": [8] * 9,
        "scaled binomial": [8 * x * (x - 1) // 2 for x in range(-4, 9)],
        "zero": [0] * 9,
    }
    for name, values in samples.items():
        print(name, membership_profile(values, 8), first_failed_level(values, 8))

