from __future__ import annotations
from typing import Callable, Iterable

def sampled_level_test(f: Callable[[int], int], points: Iterable[int], level: int) -> tuple[bool, int | None]:
    if level < 0:
        raise ValueError("level must be nonnegative")
    modulus = 2 ** level
    for z in points:
        if f(z) % modulus != 0:
            return False, z
    return True, None

from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class StrictnessWitness:
    level: int
    constant_value: int

def construct_strictness_witness(level: int) -> StrictnessWitness:
    if level < 0:
        raise ValueError("level must be nonnegative")
    return StrictnessWitness(level, 1 << level)

def verify(w: StrictnessWitness) -> bool:
    return (w.constant_value % (1 << w.level) == 0 and
            w.constant_value % (1 << (w.level + 1)) != 0)

